#include <iostream>
#include <vector>
#include <string>
#include <unordered_set>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    unordered_set<long long> seen;
    bool duplicate = false;
    for (int i = 0; i < n; i++) {
        if (seen.count(a[i])) {
            duplicate = true;
            break;
        }
        seen.insert(a[i]);
    }
    cout << (duplicate ? "yes" : "no") << "\n";

    return 0;
}

